// Guides métier : une seule source de contenu, rendue par app/info/guides/[slug]/page.tsx.
// Chaque guide est rédigé pour son métier (recherches réelles, catégories, services, réglementation)
// afin d'éviter tout contenu dupliqué. Les noms de catégories Google sont donnés à titre indicatif :
// on choisit toujours la plus proche dans la liste proposée par Google Business Profile.

export type Guide = {
  slug: string
  metier: string            // libellé court (cartes, fil d'Ariane)
  title: string             // balise <title>
  description: string       // meta description (≤ 160 caractères)
  h1: string
  intro: string
  enBref: string            // réponse directe (AEO / GEO) : citée telle quelle par les assistants IA
  card: string              // accroche de la carte sur /info/
  readMin: number
  searches: string[]        // ce que les clients tapent vraiment
  categories: { main: string; secondary: string[] }
  zone: string
  services: string[]
  photos: string
  reviews: string
  reachable: string
  extra?: { title: string; body: string; list?: string[] }
  ai: string                // GEO : être cité par ChatGPT, Gemini, AI Overviews
  tip: string
  faqs: [string, string][]
  related: string[]         // slugs des guides voisins
}

